"""
Additional edge case tests for the refactored Context class.
"""

from jinja2 import Environment

def test_nested_autoescape_blocks():
    """Test nested autoescape context changes."""
    env = Environment(autoescape=True)

    template = env.from_string("""
    Outer: {{ text }}
    {% autoescape false %}
        Middle: {{ text }}
        {% autoescape true %}
            Inner: {{ text }}
        {% endautoescape %}
        Middle again: {{ text }}
    {% endautoescape %}
    Outer again: {{ text }}
    """)

    result = template.render(text="<b>X</b>")

    # Verify autoescape is properly restored at each level
    lines = [line.strip() for line in result.split('\n') if line.strip()]

    assert "Outer: &lt;b&gt;X&lt;/b&gt;" in result
    assert "Middle: <b>X</b>" in result
    assert "Inner: &lt;b&gt;X&lt;/b&gt;" in result
    assert "Middle again: <b>X</b>" in result
    assert "Outer again: &lt;b&gt;X&lt;/b&gt;" in result

    print("✓ Nested autoescape blocks work correctly")


def test_autoescape_with_inheritance():
    """Test autoescape in inherited templates."""
    env = Environment(autoescape=False)  # Default: no autoescape

    base = env.from_string("""
    {% block content %}
        Base: {{ text }}
    {% endblock %}
    """)

    env.globals['base'] = base

    child = env.from_string("""
    {% extends base %}
    {% autoescape true %}
        {% block content %}
            Child: {{ text }}
        {% endblock %}
    {% endautoescape %}
    """)

    result = child.render(text="<i>Y</i>")

    # Inside autoescape block, text should be escaped
    assert "Child: &lt;i&gt;Y&lt;/i&gt;" in result

    print("✓ Autoescape with inheritance works correctly")


def test_block_with_autoescape_rendering():
    """Test that block rendering respects autoescape settings."""
    env = Environment(autoescape=True)

    base = env.from_string("""
    {% block safe_block %}
        Safe: {{ text }}
    {% endblock %}
    {% autoescape false %}
        {% block unsafe_block %}
            Unsafe: {{ text }}
        {% endblock %}
    {% endautoescape %}
    """)

    env.globals['base'] = base

    child = env.from_string("""
    {% extends base %}
    {% block safe_block %}
        {{ super() }}
        Child Safe: {{ text }}
    {% endblock %}
    {% block unsafe_block %}
        {{ super() }}
        Child Unsafe: {{ text }}
    {% endblock %}
    """)

    result = child.render(text="<span>Z</span>")

    # Safe blocks should escape
    assert "Safe: &lt;span&gt;Z&lt;/span&gt;" in result
    assert "Child Safe: &lt;span&gt;Z&lt;/span&gt;" in result

    # Unsafe blocks should not escape
    assert "Unsafe: <span>Z</span>" in result
    assert "Child Unsafe: <span>Z</span>" in result

    print("✓ Block rendering with autoescape works correctly")


def test_multiple_state_saves_and_reverts():
    """Test that multiple save/revert operations work correctly."""
    env = Environment(autoescape=True)

    template = env.from_string("""
    L1: {{ text }}
    {% autoescape false %}
        L2: {{ text }}
        {% autoescape true %}
            L3: {{ text }}
            {% autoescape false %}
                L4: {{ text }}
            {% endautoescape %}
            L3b: {{ text }}
        {% endautoescape %}
        L2b: {{ text }}
    {% endautoescape %}
    L1b: {{ text }}
    """)

    result = template.render(text="<x>")

    # Verify all levels maintain correct autoescape state
    assert "L1: &lt;x&gt;" in result
    assert "L2: <x>" in result
    assert "L3: &lt;x&gt;" in result
    assert "L4: <x>" in result
    assert "L3b: &lt;x&gt;" in result
    assert "L2b: <x>" in result
    assert "L1b: &lt;x&gt;" in result

    print("✓ Multiple state saves and reverts work correctly")


if __name__ == "__main__":
    test_nested_autoescape_blocks()
    test_autoescape_with_inheritance()
    test_block_with_autoescape_rendering()
    test_multiple_state_saves_and_reverts()
    print("\n✅ All edge case tests passed!")

